export function ExcessiveNesting({
  label = "{{label}}",
  fixed = {{fixed}},
  depth = {{depth}},
  accent = "{{accent}}",
}) {
  const wrap = { border: "1.5px dashed #24143033", borderRadius: 6, padding: 8 };
  let nested = <div style={{ border: "1.5px solid " + accent, borderRadius: 6, padding: 8, background: "#FAF7F2", fontWeight: 700, textAlign: "center" }}>{label}</div>;
  for (let i = 0; i < 5; i++) nested = <div style={wrap}>{nested}</div>;
  return (
    <div style={{ width: 300, fontFamily: "system-ui, sans-serif", fontSize: 13, color: "#241430" }}>
      <span style={{ display: "inline-block", padding: "3px 10px", borderRadius: 999, fontSize: 11, fontWeight: 700, marginBottom: 10, background: fixed ? "#1a7a44" : "#b3261e", color: "#FAF7F2" }}>
        {fixed ? "\u2713 Better" : "\u2717 Anti-pattern: excessive nesting (" + depth + " levels)"}
      </span>
      {!fixed && nested}
      {fixed && <div style={{ padding: 14, borderRadius: 10, background: accent, fontWeight: 700, textAlign: "center" }}>{label}</div>}
    </div>
  );
}
